// One pooled, goroutine-safe client for the whole process.
func newClient() *redis.Client {
	rdb := redis.NewClient(&redis.Options{
		Addr:         "localhost:6379",
		Password:     "",
		DB:           0,
		PoolSize:     20,               // max sockets in the pool
		MinIdleConns: 5,                // keep warm connections
		DialTimeout:  5 * time.Second,
		ReadTimeout:  3 * time.Second,
	})
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	if err := rdb.Ping(ctx).Err(); err != nil { // verify at startup
		log.Fatalf("redis unreachable: %v", err)
	}
	return rdb
	// Output: (client connected; Ping returns PONG)
}

// Each type has purpose-built commands.
func demoTypes(ctx context.Context, rdb *redis.Client) {
	rdb.Set(ctx, "page:home:views", 0, 0)          // string
	rdb.HSet(ctx, "user:42", "name", "alice", "tier", "pro") // hash
	rdb.SAdd(ctx, "post:9:tags", "go", "redis")    // set
	rdb.ZAdd(ctx, "leaderboard", redis.Z{Score: 99, Member: "alice"}) // sorted set
	rdb.LPush(ctx, "jobs", "email:welcome")         // list

	fields, _ := rdb.HGetAll(ctx, "user:42").Result()
	top, _ := rdb.ZRevRange(ctx, "leaderboard", 0, 0).Result()
	fmt.Println(fields["tier"], top)
	// Output: pro [alice]
}

// Cache-aside: try cache, fall back to DB, then populate.
func getUser(ctx context.Context, rdb *redis.Client, id string) (string, error) {
	key := "user:" + id
	val, err := rdb.Get(ctx, key).Result()
	if err == nil {
		return val, nil // cache hit
	}
	if err != redis.Nil { // real error, not a miss
		return "", err
	}
	user := loadUserFromDB(id)                       // miss -> source of truth
	rdb.Set(ctx, key, user, 10*time.Minute)          // populate with TTL
	return user, nil
}
// Output: first call hits DB; subsequent calls served from Redis

// Store a session hash with a 30-minute sliding TTL.
func saveSession(ctx context.Context, rdb *redis.Client, token, userID string) error {
	key := "session:" + token
	if err := rdb.HSet(ctx, key,
		"user_id", userID,
		"created", time.Now().Unix(),
	).Err(); err != nil {
		return err
	}
	return rdb.Expire(ctx, key, 30*time.Minute).Err() // auto-evict when idle
}

func touchSession(ctx context.Context, rdb *redis.Client, token string) {
	rdb.Expire(ctx, "session:"+token, 30*time.Minute) // slide the window on activity
}
// Output: session key lives 30m; refreshed on each request

// Fixed-window rate limit: INCR + EXPIRE on first hit.
func allow(ctx context.Context, rdb *redis.Client, clientID string, limit int64, window time.Duration) (bool, error) {
	key := "rl:" + clientID
	count, err := rdb.Incr(ctx, key).Result() // atomic increment
	if err != nil {
		return false, err
	}
	if count == 1 { // first request in this window sets the TTL
		rdb.Expire(ctx, key, window)
	}
	return count <= limit, nil
}
// Output: allow=true until the 'limit'-th call within 'window', then false

// A transactional pipeline: both commands run atomically via MULTI/EXEC.
func chargeAndLog(ctx context.Context, rdb *redis.Client, user string, amount int64) error {
	pipe := rdb.TxPipeline()
	pipe.DecrBy(ctx, "balance:"+user, amount)
	pipe.LPush(ctx, "ledger:"+user, amount)
	_, err := pipe.Exec(ctx) // one round-trip, atomic
	return err
}

func listen(ctx context.Context, rdb *redis.Client) {
	sub := rdb.Subscribe(ctx, "cache:invalidate")
	for msg := range sub.Channel() {
		fmt.Println("evict:", msg.Payload) // react to publishes
	}
}
// Output: evict: user:42  (when another node publishes)

