package main

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/redis/go-redis/v9"
)

type Product struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Price int    `json:"price"`
}

// loadFromDB is the slow source of truth (simulated).
func loadFromDB(id string) Product {
	return Product{ID: id, Name: "Widget", Price: 999}
}

func getProduct(ctx context.Context, rdb *redis.Client, id string) (Product, error) {
	key := "product:" + id
	if raw, err := rdb.Get(ctx, key).Bytes(); err == nil {
		var p Product
		return p, json.Unmarshal(raw, &p) // cache hit
	} else if err != redis.Nil {
		return Product{}, err // real error
	}
	p := loadFromDB(id) // miss -> DB
	if b, err := json.Marshal(p); err == nil {
		rdb.Set(ctx, key, b, 5*time.Minute) // populate WITH TTL
	}
	return p, nil
}

func main() {
	rdb := redis.NewClient(&redis.Options{Addr: "localhost:6379"})
	ctx := context.Background()
	p, _ := getProduct(ctx, rdb, "42") // first: DB then populate
	fmt.Println(p.Name, p.Price)
	p, _ = getProduct(ctx, rdb, "42") // second: served from Redis
	fmt.Println(p.Name, p.Price)
}

package main

import (
	"net/http"
	"strconv"
	"time"

	"github.com/redis/go-redis/v9"
)

func RateLimit(rdb *redis.Client, limit int64, window time.Duration) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			ctx := r.Context()
			key := "rl:" + r.RemoteAddr
			count, err := rdb.Incr(ctx, key).Result()
			if err != nil { // fail-open: don't take the site down if Redis blips
				next.ServeHTTP(w, r)
				return
			}
			if count == 1 {
				rdb.Expire(ctx, key, window) // start the window on first hit
			}
			if count > limit {
				w.Header().Set("Retry-After", strconv.Itoa(int(window.Seconds())))
				http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
				return
			}
			next.ServeHTTP(w, r)
		})
	}
}

package main

import (
	"context"
	"strconv"
	"time"

	"github.com/redis/go-redis/v9"
)

// allowSliding returns true if the client is under 'limit' requests in the last 'window'.
func allowSliding(ctx context.Context, rdb *redis.Client, id string, limit int64, window time.Duration) (bool, error) {
	key := "slide:" + id
	now := time.Now().UnixNano()
	min := strconv.FormatInt(now-int64(window), 10)

	pipe := rdb.TxPipeline()
	pipe.ZRemRangeByScore(ctx, key, "0", min)                        // evict old timestamps
	pipe.ZAdd(ctx, key, redis.Z{Score: float64(now), Member: now})   // record this request
	countCmd := pipe.ZCard(ctx, key)                                 // how many in window
	pipe.Expire(ctx, key, window)                                    // safety TTL
	if _, err := pipe.Exec(ctx); err != nil {
		return false, err
	}
	return countCmd.Val() <= limit, nil
}

