package solution

import (
	"context"
	"time"

	"github.com/redis/go-redis/v9"
)

// GetOrLoad implements cache-aside: cache hit, else load and populate.
func GetOrLoad(ctx context.Context, rdb *redis.Client, key string, ttl time.Duration, load func() (string, error)) (string, error) {
	val, err := rdb.Get(ctx, key).Result()
	if err == nil {
		return val, nil // hit
	}
	if err != redis.Nil {
		return "", err // real error, not a miss
	}
	// miss: load from source of truth
	val, err = load()
	if err != nil {
		return "", err // don't cache failures
	}
	if err := rdb.Set(ctx, key, val, ttl).Err(); err != nil {
		return val, err // return value even if caching fails
	}
	return val, nil
}

