func TestGetOrLoad(t *testing.T) {
	mr, _ := miniredis.Run()
	defer mr.Close()
	rdb := redis.NewClient(&redis.Options{Addr: mr.Addr()})
	ctx := context.Background()

	calls := 0
	load := func() (string, error) { calls++; return "loaded", nil }

	v, err := GetOrLoad(ctx, rdb, "k", time.Minute, load)
	if err != nil || v != "loaded" {
		t.Fatalf("miss: got %q,%v want loaded,nil", v, err)
	}
	v, err = GetOrLoad(ctx, rdb, "k", time.Minute, load)
	if err != nil || v != "loaded" {
		t.Fatalf("hit: got %q,%v", v, err)
	}
	if calls != 1 {
		t.Fatalf("load called %d times, want 1 (second read should hit cache)", calls)
	}
}

