import (
	"context"
	"time"

	"github.com/redis/go-redis/v9"
)

// Allow reports whether clientID is under the limit for the current window.
func Allow(ctx context.Context, rdb *redis.Client, clientID string, limit int64, window time.Duration) (bool, error) {
	key := "rl:" + clientID
	count, err := rdb.Incr(ctx, key).Result()
	if err != nil {
		return false, err
	}
	if count == 1 {
		// Anchor the window to the first request; don't reset on later hits.
		if err := rdb.Expire(ctx, key, window).Err(); err != nil {
			return false, err
		}
	}
	return count <= limit, nil
}

