	"testing"
	"time"

	"github.com/alicebob/miniredis/v2"
	"github.com/redis/go-redis/v9"
)

func TestAllow(t *testing.T) {
	mr, _ := miniredis.Run()
	defer mr.Close()
	rdb := redis.NewClient(&redis.Options{Addr: mr.Addr()})
	ctx := context.Background()

	for i := 1; i <= 3; i++ {
		ok, err := Allow(ctx, rdb, "c1", 3, time.Minute)
		if err != nil || !ok {
			t.Fatalf("request %d should be allowed, got %v,%v", i, ok, err)
		}
	}
	ok, _ := Allow(ctx, rdb, "c1", 3, time.Minute)
	if ok {
		t.Fatalf("4th request should be blocked")
	}
	// After the window elapses, the counter resets.
	mr.FastForward(time.Minute)
	ok, _ = Allow(ctx, rdb, "c1", 3, time.Minute)
	if !ok {
		t.Fatalf("request after window should be allowed again")
	}
}

